"""patch_marking_v1.py — MARKING-V1: precision marking layer (2026-07-03).

Paradigm shift: never mark from scratch — CORRECT A PREDICTION.
  - Assist ghost: mousedown ON a ghost = instant real marker at the ghost's
    position, then DRAG to the exact feature, release = saved. One gesture.
  - 6x LOUPE follows every drag (kills the ~2.4 frame-px/screen-px precision
    floor — the project's current error floor at median 2.1').
  - LIVE DELTA in the loupe while dragging a triangulated LM (fit by hand).
  - EPIPOLAR SNAP: line ghosts drag along their line (Alt = free).
  - Existing markers drag directly on the main canvas (no more Fix Pixel
    modal ceremony). Sub-0.5px release on a 'move' = treated as a click.
  - 'A' = inline add box at cursor with native autocomplete (existing LMs
    not yet marked here = 2nd sources, suggested first).
  - Alt+arrows = 0.2px nudge of the hovered marker (Shift = 1px).
  - After each save: toast shows the next P1 ghost (marking rhythm).
Also supersedes a latent bug: the legacy placement click ignored mainZoom
(markers placed wrong while zoomed); this layer maps through canvasToImg.
Headless-tested (Playwright): arm/drag/loupe/cancel/move-drag, zero JS errors.
Idempotent. Backup: .bak_marking. Restart server + hard refresh after.
"""
import shutil, sys
P = 'tools/calib.html'
s = open(P).read()
if 'MARKING-V1' in s:
    print('deja patche'); sys.exit(0)
shutil.copy(P, P + '.bak_marking')
BLOCK = '\n<!-- [MARKING-V1] precision marking layer: loupe, drag, inline add -->\n<div id="mk-loupe" style="display:none;position:fixed;z-index:400;pointer-events:none">\n  <canvas id="mk-loupe-cv" width="160" height="160"\n    style="border-radius:50%;border:2px solid #4ade80;box-shadow:0 4px 18px #000c;background:#000"></canvas>\n  <div id="mk-loupe-info" style="text-align:center;font-family:var(--mono,monospace);font-size:11px;\n    color:#4ade80;background:#000c;border-radius:5px;padding:2px 6px;margin-top:4px"></div>\n</div>\n<div id="mk-add-box" style="display:none;position:fixed;z-index:401;background:var(--surface,#16161c);\n  border:1px solid #4ade80;border-radius:6px;padding:8px;box-shadow:0 4px 18px #000c">\n  <input id="mk-add-input" list="mk-add-list" type="text" placeholder="LM name (existing = 2nd source)"\n    style="font-family:var(--mono,monospace);font-size:11px;background:var(--surface2,#0f0f14);\n    border:1px solid var(--border,#333);color:var(--text,#ddd);padding:5px 8px;border-radius:4px;width:260px;outline:none">\n  <datalist id="mk-add-list"></datalist>\n  <div style="font-family:var(--mono,monospace);font-size:9px;color:var(--mid,#888);margin-top:4px">\n    Enter = arm &amp; drag-place · Esc = cancel</div>\n</div>\n\n<script>\n// ══ [MARKING-V1] Precision marking: ghost-click -> instant marker -> drag ══\n// Paradigm: never mark from scratch — correct a prediction. Ghost = the\n// model\'s best guess; the human slides it to the truth. Loupe (6x) kills the\n// display-scale precision floor (~2.4 frame-px/screen-px). Live delta while\n// dragging a triangulated LM. Epipolar snap for line ghosts (Alt = free).\n(() => {\n  const MAG = 6, LOUPE = 160;\n  const loupe = document.getElementById(\'mk-loupe\');\n  const loupeCv = document.getElementById(\'mk-loupe-cv\');\n  const loupeCtx = loupeCv.getContext(\'2d\');\n  const loupeInfo = document.getElementById(\'mk-loupe-info\');\n  const addBox = document.getElementById(\'mk-add-box\');\n  const addInput = document.getElementById(\'mk-add-input\');\n  const _imgs = new Map();   // cam -> Image (full res)\n  const mk = { drag: null, swallowClick: false, nudgeTimer: null };\n  window._mk = mk;  // test hook\n\n  function fullImg(cam) {\n    if (_imgs.has(cam)) return _imgs.get(cam);\n    const im = new Image();\n    im.src = \'/frame/\' + encodeURIComponent(cam);\n    _imgs.set(cam, im);\n    return im;\n  }\n\n  function imgPt(e) {\n    const rect = getMainPaneRect();\n    return canvasToImg(e.clientX - rect.left, e.clientY - rect.top);\n  }\n\n  function vfovDeg() {\n    if (!camData?.size) return null;\n    const [w, h] = camData.size;\n    const hf = (typeof params !== \'undefined\' && params.hfov) ? params.hfov : null;\n    if (!hf) return null;\n    return 2 * Math.atan(Math.tan(hf * Math.PI / 360) * h / w) * 180 / Math.PI;\n  }\n\n  function liveDelta(lm, px) {\n    const p = projections.find(x => x.name === lm);\n    if (!p || !p.proj || !camData?.size) return null;\n    const [w, h] = camData.size;\n    const hf = params.hfov, vf = vfovDeg();\n    if (!hf || !vf) return null;\n    const dx = (p.proj[0] - px[0]) * hf / w * 60;\n    const dy = (p.proj[1] - px[1]) * vf / h * 60;\n    return Math.hypot(dx, dy);\n  }\n\n  function epipolarFor(lm) {\n    for (const g of (ghostMarkers1 || []))\n      if (g.type === \'epipolar\' && g.name === lm) return g.line;\n    return null;\n  }\n\n  function snapToLine(px, line) {\n    const [a, b] = line;\n    const abx = b[0] - a[0], aby = b[1] - a[1];\n    const t = Math.max(0, Math.min(1,\n      ((px[0] - a[0]) * abx + (px[1] - a[1]) * aby) / (abx * abx + aby * aby)));\n    return [a[0] + t * abx, a[1] + t * aby];\n  }\n\n  function markerHit(e) {\n    const rect = getMainPaneRect();\n    const mx = e.clientX - rect.left, my = e.clientY - rect.top;\n    for (const p of (projections || [])) {\n      if (!p.marked_pixel) continue;\n      const [cx, cy] = toCanvas(p.marked_pixel[0], p.marked_pixel[1]);\n      if ((mx - cx) ** 2 + (my - cy) ** 2 < 100) return p;\n    }\n    return null;\n  }\n\n  function showLoupe(e, px, lm) {\n    const im = fullImg(currentCam);\n    loupe.style.display = \'block\';\n    const lx = Math.min(window.innerWidth - LOUPE - 20, e.clientX + 26);\n    const ly = Math.max(10, e.clientY - LOUPE - 30);\n    loupe.style.left = lx + \'px\';\n    loupe.style.top = ly + \'px\';\n    loupeCtx.fillStyle = \'#000\';\n    loupeCtx.fillRect(0, 0, LOUPE, LOUPE);\n    if (im.complete && im.naturalWidth) {\n      const src = LOUPE / MAG;\n      loupeCtx.imageSmoothingEnabled = false;\n      loupeCtx.drawImage(im, px[0] - src / 2, px[1] - src / 2, src, src, 0, 0, LOUPE, LOUPE);\n    }\n    loupeCtx.strokeStyle = \'#4ade80\'; loupeCtx.lineWidth = 1;\n    loupeCtx.beginPath();\n    loupeCtx.moveTo(LOUPE / 2, 0); loupeCtx.lineTo(LOUPE / 2, LOUPE);\n    loupeCtx.moveTo(0, LOUPE / 2); loupeCtx.lineTo(LOUPE, LOUPE / 2);\n    loupeCtx.stroke();\n    const d = liveDelta(lm, px);\n    loupeInfo.textContent = lm.slice(0, 26) + \' · \' + px[0].toFixed(1) + \',\' + px[1].toFixed(1) +\n      (d != null ? " · d=" + d.toFixed(2) + "\'" : \'\');\n    loupeInfo.style.color = d == null ? \'#c084fc\' : d < 1 ? \'#4ade80\' : d < 5 ? \'#f59e0b\' : \'#f87171\';\n  }\n\n  function paintPending() {\n    if (!mk.drag) return;\n    draw();\n    const [cx, cy] = toCanvas(mk.drag.px[0], mk.drag.px[1]);\n    ctx.save();\n    ctx.strokeStyle = \'#4ade80\'; ctx.lineWidth = 2;\n    ctx.beginPath(); ctx.arc(cx, cy, 7, 0, Math.PI * 2); ctx.stroke();\n    ctx.beginPath();\n    ctx.moveTo(cx - 12, cy); ctx.lineTo(cx - 4, cy);\n    ctx.moveTo(cx + 4, cy); ctx.lineTo(cx + 12, cy);\n    ctx.moveTo(cx, cy - 12); ctx.lineTo(cx, cy - 4);\n    ctx.moveTo(cx, cy + 4); ctx.lineTo(cx, cy + 12);\n    ctx.stroke();\n    ctx.restore();\n  }\n\n  function beginDrag(kind, lm, px, e, isNew) {\n    mk.drag = { kind, lm, px, isNew: !!isNew, line: epipolarFor(lm) };\n    fullImg(currentCam);\n    canvasWrap.style.cursor = \'none\';\n    showLoupe(e, px, lm);\n    paintPending();\n  }\n\n  async function commit() {\n    const d = mk.drag;\n    mk.drag = null;\n    loupe.style.display = \'none\';\n    canvasWrap.style.cursor = \'crosshair\';\n    const nx = Math.round(d.px[0] * 10) / 10, ny = Math.round(d.px[1] * 10) / 10;\n    const ep = d.kind === \'place\' ? \'/api/add_pixel\' : \'/api/set_pixel\';\n    const nf = d.isNew ? \'&new=1\' : \'\';\n    const res = await fetch(ep + \'?cam=\' + encodeURIComponent(currentCam) +\n      \'&lm=\' + encodeURIComponent(d.lm) + \'&px=\' + nx + \'&py=\' + ny + nf).then(r => r.json());\n    if (res.ok) {\n      addPxMode = false;\n      await loadProjections();\n      if (window._refreshGhosts) window._refreshGhosts();\n      // auto-advance hint: next P1 ghost\n      const next = (ghostMarkers1 || []).find(g => g.type === \'point\' && g.priority === 1 && g.name !== d.lm);\n      const t = document.getElementById(\'tri-toast\');\n      if (t) {\n        document.getElementById(\'tri-toast-title\').textContent = d.lm + \' @ \' + nx + \',\' + ny + \' saved\';\n        document.getElementById(\'tri-toast-meta\').textContent =\n          next ? \'next P1: \' + next.name + \' (click its ghost)\' : \'\';\n        t.style.display = \'block\';\n        setTimeout(() => { t.style.display = \'none\'; }, 2600);\n      }\n    } else {\n      alert(res.error || \'save failed\');\n    }\n  }\n\n  // ── capture-phase mousedown: take over marking gestures ──\n  canvasWrap.addEventListener(\'mousedown\', e => {\n    if (e.button !== 0) return;\n    if (e.target.closest && e.target.closest(\'#pane-2, #trace-pop, #mesh-ctrl-pop\')) return;\n    if (typeof fanPushOn !== \'undefined\' && fanPushOn) return;\n    if (typeof traceMode !== \'undefined\' && traceMode) return;\n    // 1. armed placement (assist ghost click or +Add/inline): drag-place\n    if (addPxMode && addPxSelectedLm) {\n      const g = (ghostMarkers1 || []).find(x => x.type === \'point\' && x.name === addPxSelectedLm);\n      const start = (window._assistHoverGhost === addPxSelectedLm && g) ? g.pixel.slice() : imgPt(e);\n      beginDrag(\'place\', addPxSelectedLm, start, e, !!window._mkAddIsNew);\n      e.stopImmediatePropagation(); e.preventDefault();\n      mk.swallowClick = true;\n      return;\n    }\n    // 2. assist mode: mousedown directly on a point ghost = instant marker + drag\n    if (document.body.classList.contains(\'assist-on\') && window._assistHoverGhost) {\n      const g = (ghostMarkers1 || []).find(x => x.type === \'point\' && x.name === window._assistHoverGhost);\n      if (g) {\n        addPxSelectedLm = g.name;\n        beginDrag(\'place\', g.name, g.pixel.slice(), e, false);\n        e.stopImmediatePropagation(); e.preventDefault();\n        mk.swallowClick = true;\n        return;\n      }\n    }\n    // 3. drag an existing marker\n    const hit = markerHit(e);\n    if (hit) {\n      beginDrag(\'move\', hit.name, hit.marked_pixel.slice(), e, false);\n      mk.drag.orig = hit.marked_pixel.slice();\n      e.stopImmediatePropagation(); e.preventDefault();\n      mk.swallowClick = true;\n      return;\n    }\n  }, true);\n\n  window.addEventListener(\'mousemove\', e => {\n    if (!mk.drag) return;\n    let px = imgPt(e);\n    if (mk.drag.line && !e.altKey) px = snapToLine(px, mk.drag.line);\n    mk.drag.px = px;\n    showLoupe(e, px, mk.drag.lm);\n    paintPending();\n  });\n\n  window.addEventListener(\'mouseup\', e => {\n    if (!mk.drag) return;\n    const d = mk.drag;\n    // moved less than 0.5 img px on a \'move\' drag = accidental click -> revert\n    if (d.kind === \'move\' && d.orig &&\n        Math.hypot(d.px[0] - d.orig[0], d.px[1] - d.orig[1]) < 0.5) {\n      mk.drag = null;\n      loupe.style.display = \'none\';\n      canvasWrap.style.cursor = \'crosshair\';\n      draw();\n      return;\n    }\n    commit();\n  });\n\n  canvasWrap.addEventListener(\'click\', e => {\n    if (mk.swallowClick) { mk.swallowClick = false; e.stopImmediatePropagation(); e.preventDefault(); }\n  }, true);\n\n  // ── Alt+arrows: sub-pixel nudge of the hovered marker ──\n  document.addEventListener(\'keydown\', async e => {\n    if (!e.altKey || mk.drag) return;\n    if (!hoveredLm) return;\n    const step = e.shiftKey ? 1.0 : 0.2;\n    const map = { ArrowLeft: [-step, 0], ArrowRight: [step, 0], ArrowUp: [0, -step], ArrowDown: [0, step] };\n    const dxy = map[e.key];\n    if (!dxy) return;\n    e.preventDefault(); e.stopImmediatePropagation();\n    const p = projections.find(x => x.name === hoveredLm);\n    if (!p || !p.marked_pixel) return;\n    p.marked_pixel[0] = Math.round((p.marked_pixel[0] + dxy[0]) * 10) / 10;\n    p.marked_pixel[1] = Math.round((p.marked_pixel[1] + dxy[1]) * 10) / 10;\n    draw();\n    clearTimeout(mk.nudgeTimer);\n    const lm = hoveredLm, npx = p.marked_pixel.slice();\n    mk.nudgeTimer = setTimeout(async () => {\n      await fetch(\'/api/set_pixel?cam=\' + encodeURIComponent(currentCam) +\n        \'&lm=\' + encodeURIComponent(lm) + \'&px=\' + npx[0] + \'&py=\' + npx[1]).then(r => r.json());\n      await loadProjections();\n    }, 450);\n  }, true);\n\n  // ── \'A\' inline add with autocomplete (existing LM = 2nd source first) ──\n  let _allLms = null;\n  document.addEventListener(\'keydown\', async e => {\n    if (e.key !== \'a\' && e.key !== \'A\') return;\n    if (e.target.tagName === \'INPUT\' || e.target.tagName === \'TEXTAREA\') return;\n    if (mk.drag || addPxMode) return;\n    if (e.altKey || e.ctrlKey || e.metaKey) return;\n    e.preventDefault();\n    if (_allLms === null) {\n      try { _allLms = (await fetch(\'/api/all_landmarks\').then(r => r.json())).landmarks || []; }\n      catch (_) { _allLms = []; }\n      const dl = document.getElementById(\'mk-add-list\');\n      const markedHere = new Set((projections || []).filter(p => p.marked_pixel).map(p => p.name));\n      for (const n of _allLms) {\n        if (markedHere.has(n)) continue;\n        const o = document.createElement(\'option\');\n        o.value = n;\n        dl.appendChild(o);\n      }\n    }\n    addBox.style.left = Math.min(window.innerWidth - 300, (window._mkMouseX || 300)) + \'px\';\n    addBox.style.top = Math.max(10, (window._mkMouseY || 200) - 60) + \'px\';\n    addBox.style.display = \'block\';\n    addInput.value = \'\';\n    addInput.focus();\n  });\n  window.addEventListener(\'mousemove\', e => { window._mkMouseX = e.clientX; window._mkMouseY = e.clientY; });\n  addInput.addEventListener(\'keydown\', e => {\n    if (e.key === \'Escape\') { addBox.style.display = \'none\'; return; }\n    if (e.key !== \'Enter\') return;\n    const name = addInput.value.trim();\n    if (!name) return;\n    addBox.style.display = \'none\';\n    window._mkAddIsNew = !(_allLms || []).includes(name);\n    addPxSelectedLm = name;\n    addPxMode = true;\n    canvasWrap.style.cursor = \'crosshair\';\n    const t = document.getElementById(\'tri-toast\');\n    if (t) {\n      document.getElementById(\'tri-toast-title\').textContent = \'Marking armed: \' + name + (window._mkAddIsNew ? \' (new)\' : \' (2nd source)\');\n      document.getElementById(\'tri-toast-meta\').textContent = \'Press and drag on the frame · loupe follows · release = save\';\n      t.style.display = \'block\';\n      setTimeout(() => { t.style.display = \'none\'; }, 4000);\n    }\n  });\n\n  document.addEventListener(\'keydown\', e => {\n    if (e.key === \'Escape\' && mk.drag) {\n      mk.drag = null;\n      loupe.style.display = \'none\';\n      canvasWrap.style.cursor = \'crosshair\';\n      draw();\n    }\n  });\n\n  console.log(\'[MARKING-V1] precision marking layer active\');\n})();\n</script>\n'
anchor = '</body>'
assert anchor in s, 'anchor body introuvable'
i = s.rindex(anchor)
s = s[:i] + BLOCK + s[i:]
open(P, 'w').write(s)
print('MARKING-V1 applique. pkill le serveur, relance, hard refresh.')
